'use client';

import { useState } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import { WordRoll } from '@/components/core/word-roll';
import {
  type AutoplayStep,
  useAutoplay,
} from '@/registry/ndeko/hooks/use-autoplay';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Button } from '@/registry/ndeko/ui/button';
import { CompanyMark } from '@/registry/ndeko/ui/company-mark';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { type Segment, Segments } from '@/registry/ndeko/ui/segments';
import { Wash } from '@/registry/ndeko/ui/wash';

import { type BillingPeriod, PLAN, SECTION } from './data';
import { PatternFrame, type PatternKind } from './pattern-frame';

const MONTHS_PER_YEAR = 12;

const PERIODS: Segment<BillingPeriod>[] = [
  { value: 'monthly', label: 'Monthly' },
  { value: 'yearly', label: 'Yearly' },
];

const PERIOD_ORDER: Record<BillingPeriod, number> = {
  monthly: 0,
  yearly: 1,
};

const PRICE_FORMAT: Intl.NumberFormatOptions = {
  style: 'currency',
  currency: 'USD',
  maximumFractionDigits: 0,
};

const PRICE_FORMATTER = new Intl.NumberFormat('en-US', PRICE_FORMAT);

const LOOP_AFTER_MS = 2000;

const NO_STEPS: AutoplayStep[] = [];

function monthlyFigureOf(period: BillingPeriod) {
  if (period === 'yearly') {
    return PLAN.yearlyPrice / MONTHS_PER_YEAR;
  }
  return PLAN.monthlyPrice;
}

function billingNoteOf(period: BillingPeriod) {
  if (period === 'yearly') {
    const total = PRICE_FORMATTER.format(PLAN.yearlyPrice);
    return `Billed ${total} once a year`;
  }
  return 'Billed every month';
}

/** Without a switch the drift of the pattern is all the plan has to show. */
function stepsOf(hasBillingSwitch: boolean, switchSteps: AutoplayStep[]) {
  if (hasBillingSwitch) {
    return switchSteps;
  }
  return NO_STEPS;
}

/** An empty script that loops would wake the piece for nothing at every round. */
function loopAfterOf(hasBillingSwitch: boolean) {
  if (hasBillingSwitch) {
    return LOOP_AFTER_MS;
  }
  return undefined;
}

function announcementOf(period: BillingPeriod) {
  const figure = monthlyFigureOf(period);
  const price = PRICE_FORMATTER.format(figure);
  const note = billingNoteOf(period);
  return `${price} a month. ${note}.`;
}

export type Pricing05Props = {
  /** The hairline pattern drawn around the plan. */
  pattern?: PatternKind;
  /** Without it the plan shows its monthly price only. */
  hasBillingSwitch?: boolean;
};

export default function Pricing05({
  pattern = 'zigzag',
  hasBillingSwitch = true,
}: Pricing05Props) {
  const [period, setPeriod] = useState<BillingPeriod>('monthly');
  const [announcement, setAnnouncement] = useState('');
  const figure = monthlyFigureOf(period);
  const note = billingNoteOf(period);
  const periodOrder = PERIOD_ORDER[period];

  /** Only a person's choice is said: the demonstration moves the same switch in silence. */
  function changePeriod(next: BillingPeriod) {
    setPeriod(next);
    setAnnouncement(announcementOf(next));
  }

  function startOver() {
    setPeriod('monthly');
  }

  const switchSteps: AutoplayStep[] = [
    { after: 2600, run: () => setPeriod('yearly') },
    { after: 3400, run: () => setPeriod('monthly') },
  ];
  const steps = stepsOf(hasBillingSwitch, switchSteps);
  const loopAfter = loopAfterOf(hasBillingSwitch);
  const { ref } = useAutoplay<HTMLDivElement>(steps, {
    loopAfter,
    onReset: startOver,
  });

  return (
    <section className='@container'>
      <div
        ref={ref}
        className='mx-auto flex max-w-5xl flex-col items-center gap-10 px-4 py-16 @2xl:px-6 @2xl:py-24'
      >
        <div className='flex max-w-xl flex-col items-center gap-3 text-center'>
          <h2 className='text-2xl font-semibold text-balance @2xl:text-3xl'>
            {SECTION.title}
          </h2>
          <p className='text-muted-foreground text-base text-pretty'>
            {SECTION.description}
          </p>
        </div>
        <PatternFrame pattern={pattern} className='w-full max-w-xl'>
          <article className='surface-brand relative isolate flex flex-col gap-6 rounded-xl p-6 @md:p-7'>
            <Wash />
            <div className='flex items-center gap-3'>
              <CompanyMark seed={PLAN.product} size='lg' />
              <div className='flex min-w-0 flex-col gap-0.5'>
                <h3 className='text-sm font-medium'>{PLAN.product}</h3>
                <p className='text-muted-foreground text-xs text-pretty'>
                  {PLAN.description}
                </p>
              </div>
            </div>
            {hasBillingSwitch && (
              <div className='flex flex-wrap items-center gap-2'>
                <Segments
                  value={period}
                  segments={PERIODS}
                  onValueChange={changePeriod}
                  label='Billing period'
                />
                <Badge variant='secondary'>{PLAN.yearlyNote}</Badge>
              </div>
            )}
            <div className='flex flex-col gap-1'>
              <p className='flex items-baseline gap-1.5'>
                <MotionNumber
                  value={figure}
                  format={PRICE_FORMAT}
                  className='text-5xl font-semibold'
                />
                <span className='text-muted-foreground text-[13px]'>
                  per month
                </span>
              </p>
              <p className='text-muted-foreground text-xs tabular-nums'>
                <WordRoll text={note} value={periodOrder} />
              </p>
            </div>
            <Button size='lg' nativeButton={false} render={<a href='#' />}>
              {PLAN.action}
            </Button>
            <ul className='flex flex-col gap-2.5 text-[13px]'>
              {PLAN.features.map((feature) => (
                <li key={feature} className='flex items-center gap-2.5'>
                  <span
                    aria-hidden='true'
                    className='bg-foreground/25 size-1 shrink-0 rounded-full'
                  />
                  {feature}
                </li>
              ))}
            </ul>
            <p className='text-muted-foreground text-xs text-pretty'>
              {PLAN.trial}
            </p>
          </article>
        </PatternFrame>
        <p className='text-muted-foreground text-center text-xs'>
          {SECTION.footnote}
        </p>
      </div>
      <LiveRegion message={announcement} />
    </section>
  );
}

'use client';

import { useInView } from 'motion/react';
import {
  type CSSProperties,
  type ReactNode,
  type RefObject,
  useEffect,
  useId,
  useRef,
} from 'react';

import { useDocumentVisible } from '@/registry/ndeko/hooks/use-agent-run';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { cn } from '@/registry/ndeko/lib/utils';

export type PatternKind = 'zigzag' | 'stripes' | 'grid' | 'dots';

type PatternTile = {
  width: number;
  height: number;
  /** One whole tile in the direction of the drift, so each loop ends exactly where it began. */
  driftX: number;
  driftY: number;
  shape: ReactNode;
};

/** The time the pattern takes to drift by one tile, slow enough to read as a texture. */
const DRIFT_MS = 3200;

const UNSAFE_ID_CHARACTERS = /[^a-zA-Z0-9_-]/g;

const HAIRLINE: CSSProperties = { strokeWidth: 'var(--hairline, 1px)' };

const TILES: Record<PatternKind, PatternTile> = {
  zigzag: {
    width: 16,
    height: 10,
    driftX: 16,
    driftY: 0,
    shape: (
      <path
        d='M0 7.5 4 2.5 8 7.5 12 2.5 16 7.5'
        fill='none'
        stroke='currentColor'
        strokeLinejoin='round'
        style={HAIRLINE}
      />
    ),
  },
  stripes: {
    width: 10,
    height: 10,
    driftX: 10,
    driftY: 0,
    shape: (
      <path
        d='M-2.5 2.5 2.5-2.5M0 10 10 0M7.5 12.5 12.5 7.5'
        fill='none'
        stroke='currentColor'
        style={HAIRLINE}
      />
    ),
  },
  grid: {
    width: 16,
    height: 16,
    driftX: 16,
    driftY: 16,
    shape: (
      <path
        d='M16 0H0V16'
        fill='none'
        stroke='currentColor'
        shapeRendering='crispEdges'
        style={HAIRLINE}
      />
    ),
  },
  dots: {
    width: 12,
    height: 12,
    driftX: 12,
    driftY: 12,
    shape: <circle cx='6' cy='6' r='1' fill='currentColor' />,
  },
};

function driftFramesOf(tile: PatternTile): Keyframe[] {
  return [
    { transform: 'translate(0px, 0px)' },
    { transform: `translate(${tile.driftX}px, ${tile.driftY}px)` },
  ];
}

/** The layer reaches one tile past the top and left edges, so the drift never uncovers a corner. */
function layerStyleOf(tile: PatternTile): CSSProperties {
  const top = -tile.driftY;
  const left = -tile.driftX;
  return { top, left, right: 0, bottom: 0 };
}

/**
 * One Web Animation on the transform of the layer, made once and only paused or played: it runs
 * on the compositor while the frame is on screen and stays where it stopped when it leaves.
 */
function useDrift(
  layerRef: RefObject<HTMLDivElement | null>,
  tile: PatternTile,
  isDrifting: boolean,
  shouldReduceMotion: boolean
) {
  const animationRef = useRef<Animation | null>(null);

  useEffect(() => {
    const layer = layerRef.current;
    if (!layer) {
      return;
    }
    if (shouldReduceMotion) {
      return;
    }
    const frames = driftFramesOf(tile);
    const animation = layer.animate(frames, {
      duration: DRIFT_MS,
      iterations: Infinity,
      easing: 'linear',
    });
    animation.pause();
    animationRef.current = animation;
    return () => {
      animation.cancel();
      animationRef.current = null;
    };
  }, [layerRef, tile, shouldReduceMotion]);

  useEffect(() => {
    const animation = animationRef.current;
    if (!animation) {
      return;
    }
    if (isDrifting) {
      animation.play();
      return;
    }
    animation.pause();
  }, [isDrifting, tile, shouldReduceMotion]);
}

type PatternFrameProps = {
  pattern: PatternKind;
  className?: string;
  children: ReactNode;
};

/**
 * A tray drawn with a pattern of hairlines around a solid panel. The pattern drifts while the
 * tray is on screen, stops off screen and in a hidden tab, and stays still under reduced motion.
 */
export function PatternFrame({
  pattern,
  className,
  children,
}: PatternFrameProps) {
  const frameRef = useRef<HTMLDivElement>(null);
  const layerRef = useRef<HTMLDivElement>(null);
  const rawId = useId();
  const isInView = useInView(frameRef, { amount: 0.2 });
  const isVisible = useDocumentVisible();
  const shouldReduceMotion = usePrefersReducedMotion();
  const safeId = rawId.replace(UNSAFE_ID_CHARACTERS, '');
  const patternId = `pattern-${safeId}`;
  const tile = TILES[pattern];
  const layerStyle = layerStyleOf(tile);
  const isDrifting = isInView && isVisible;

  useDrift(layerRef, tile, isDrifting, shouldReduceMotion);

  return (
    <div
      ref={frameRef}
      className={cn(
        'bg-foreground/[0.02] relative isolate overflow-hidden rounded-2xl p-5 @md:p-10',
        className
      )}
    >
      <div
        aria-hidden='true'
        className='pointer-events-none absolute inset-0 -z-10'
      >
        <div ref={layerRef} style={layerStyle} className='absolute'>
          <svg className='text-border size-full'>
            <defs>
              <pattern
                id={patternId}
                width={tile.width}
                height={tile.height}
                patternUnits='userSpaceOnUse'
              >
                {tile.shape}
              </pattern>
            </defs>
            <rect width='100%' height='100%' fill={`url(#${patternId})`} />
          </svg>
        </div>
      </div>
      {children}
    </div>
  );
}

export type BillingPeriod = 'monthly' | 'yearly';

export const PLAN = {
  product: 'Inkpond',
  description: 'Everything Inkpond does, on every device you write on',
  monthlyPrice: 12,
  yearlyPrice: 120,
  yearlyNote: 'Two months free',
  features: [
    'Unlimited documents and notebooks',
    'Sync on Mac, Windows, iPhone and Android',
    'Every version kept for a year',
    'Export to PDF, EPUB and Markdown',
    'Shared notebooks with up to three people',
  ],
  action: 'Start writing',
  trial: '14 days free, cancel from your account at any time',
};

export const SECTION = {
  title: 'One plan with every part of Inkpond',
  description:
    'Write on any device, keep every version and export when the draft is done. Pay each month, or once a year for two months free.',
  footnote:
    'Illustrative prices in US dollars for an example app, taxes added at checkout',
};
